CREATE TABLE flash_sale_scope_lock (edition_id BIGINT NOT NULL,region_code VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(edition_id,region_code,currency),CONSTRAINT ck_flash_sale_scope_region CHECK(REGEXP_LIKE(region_code,'^[A-Z0-9-]{2,16}$','c')),CONSTRAINT ck_flash_sale_scope_currency CHECK(REGEXP_LIKE(currency,'^[A-Z]{3}$','c')),CONSTRAINT fk_flash_sale_scope_edition FOREIGN KEY(edition_id) REFERENCES game_edition(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
